# Generated by `cargo xtask formula` in https://github.com/michel-onstein/acs for each release
# (scripts/update-tap.sh): edit the generator there, not this file.
#
# acs releases are signed; SHA256SUMS.sig is checked against this key:
#   ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAILbxQW5C9X7CdwcQ4bab0gsQi4Evk2xfgmI/972dlHCb acs release signing
# Verify a release by hand:
#   printf 'releases@acs namespaces="acs-release" %s\n' "$key" > allowed
#   ssh-keygen -Y verify -f allowed -I releases@acs -n acs-release -s SHA256SUMS.sig < SHA256SUMS
class Acs < Formula
  desc "Persistent, reconnecting remote shells over ssh"
  homepage "https://github.com/michel-onstein/acs"
  license "MIT"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/michel-onstein/acs/releases/download/v0.19.0/acs-0.19.0-aarch64-apple-darwin.tar.gz"
      sha256 "528282ae710e3034655301522064ca7bfb81bd8d9dcfe417dc77b73acfc3e542"
    end

    on_intel do
      url "https://github.com/michel-onstein/acs/releases/download/v0.19.0/acs-0.19.0-x86_64-apple-darwin.tar.gz"
      sha256 "a3f8d3f36141f77b8a4d792ec69129780a352ce7b248d09d36ef69b1cc0b3bb7"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/michel-onstein/acs/releases/download/v0.19.0/acs-0.19.0-aarch64-unknown-linux-musl.tar.gz"
      sha256 "f74ff9836d0283f6dc4d53be33fe74d4621f1e87ea5cfb9cb6866e3d033386e9"
    end

    on_intel do
      url "https://github.com/michel-onstein/acs/releases/download/v0.19.0/acs-0.19.0-x86_64-unknown-linux-musl.tar.gz"
      sha256 "5679e7e0af5990c8eefd62a9a919b9f036ff4577fd1a154d8ac88b146f27efd1"
    end
  end

  def install
    bin.install "acs"
  end

  test do
    out = shell_output("#{bin}/acs --version")
    assert_match "acs #{version} ", out
    remotes = out[/^installs remotes: (.*)$/, 1].to_s.split(", ")
    assert_includes remotes, "x86_64-unknown-linux-musl"
    assert_includes remotes, "aarch64-unknown-linux-musl"
  end
end
